-- State transitions declared for PurchaseAgreement: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION buying.purchase_agreements_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'cancelled'), ('draft', 'open'), ('open', 'cancelled'), ('open', 'done'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: purchase_agreements.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_purchase_agreements__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS purchase_agreements_status_transition_check ON buying.purchase_agreements;
CREATE TRIGGER purchase_agreements_status_transition_check
    BEFORE UPDATE OF "status" ON buying.purchase_agreements
    FOR EACH ROW EXECUTE FUNCTION buying.purchase_agreements_status_transition_check();
